theorem ArtinG.ComplementTable.output_append.{u_1, u_2} : ∀ {S : Type u_1} {E : Type u_2}
  (T : ArtinG.ComplementTable S E) (e : E) (u v : List S),
  T.output e (u ++ v) = T.output e u ++ T.output (T.residual e u) v

theorem ArtinG.ComplementTable.firstHitDFA_correct_from.{u_1, u_2} : ∀ {S : Type u_1} {E : Type u_2}
  [inst : DecidableEq E] (T : ArtinG.ComplementTable S E) (start e : E) (v : List S),
  (T.firstHitDFA start).evalFrom (some e) v = some T.identity ↔ T.FirstHit e v

theorem ArtinG.Completeness.evalWord_map.{u_1, u_2, u_3} : ∀ {S : Type u_1} {M : Type u_2} {G : Type u_3}
  [inst : Monoid M] [inst_1 : Monoid G] (iota : M →* G) (a : S → M) (p : List S),
  iota (ArtinG.evalWord a p) = ArtinG.evalWord (fun s => iota (a s)) p
